import{_ as t,o as n,c as o,a2 as a}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse('{"title":"Connect data sources","description":"SnapTrade brokerage, exchange API keys, Hyperliquid watch-only wallets, read-only permissions, expected data, and source limits.","frontmatter":{"title":"Connect data sources","description":"SnapTrade brokerage, exchange API keys, Hyperliquid watch-only wallets, read-only permissions, expected data, and source limits.","audience":"user","status":"current","last_verified":"2026-07-19T00:00:00.000Z"},"headers":[],"relativePath":"get-started/connect-data-sources.md","filePath":"get-started/connect-data-sources.md","lastUpdated":null}'),r={name:"get-started/connect-data-sources.md"};function s(i,e,c,l,d,p){return n(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="connect-data-sources" tabindex="-1">Connect data sources</h1><p>Zenin reads your data through <strong>read-only</strong> connections. It does not need, and should not be given, trade-execution permission. Connecting a source lets Zenin import holdings, balances, and executions so your research and portfolio stay in context.</p><h2 id="snaptrade-brokerage-connection" tabindex="-1">SnapTrade brokerage connection</h2><p>SnapTrade connects brokerage accounts to Zenin without sharing your broker login.</p><ol><li>Open <strong>Settings → Connected accounts</strong> (or the connection prompt).</li><li>Choose your broker and authenticate through SnapTrade.</li><li>Authorize <strong>read-only</strong> access to holdings, balances, and executions.</li><li>Return to Zenin; the connection appears as <strong>connected</strong>.</li></ol><p><strong>Expected data:</strong> holdings, cash balances, and executed trades from the linked brokerage account.</p><p><strong>Limitations:</strong> coverage depends on the broker SnapTrade supports and the permissions you grant. Live order routing is never enabled through this connection.</p><h2 id="exchange-api-keys" tabindex="-1">Exchange API keys</h2><p>For exchanges that support API access, add a <strong>read-only</strong> key.</p><ol><li>Create an API key in the exchange&#39;s dashboard.</li><li>Restrict it to <strong>read-only</strong> (no trade, no withdraw).</li><li>Paste the public key and secret into Zenin&#39;s connection form.</li><li>Save; Zenin verifies the key is read-only before storing it encrypted.</li></ol><blockquote><p>If the exchange reports trading or withdrawal permission on the key, Zenin <strong>rejects</strong> it. Use a read-only key only.</p></blockquote><p><strong>Limitations:</strong> sync availability varies by exchange. Some venues are watch-only addresses rather than API keys (see Hyperliquid below).</p><h2 id="hyperliquid-watch-only-wallets" tabindex="-1">Hyperliquid watch-only wallets</h2><p>For Hyperliquid, connect a <strong>public watch-only address</strong> instead of an API key.</p><ol><li>Enter your Hyperliquid wallet address.</li><li>Zenin imports live portfolio context from the public address — no secret required.</li></ol><p><strong>Limitations:</strong> a watch-only address shows public on-chain context. It does not grant Zenin any write access.</p><h2 id="source-limitations-applies-to-all-connections" tabindex="-1">Source limitations (applies to all connections)</h2><ul><li>Upstream services can be <strong>rate-limited, incomplete, delayed, or unavailable</strong>.</li><li>Coverage varies by asset class, instrument, and provider.</li><li>Some results may be <strong>cached, stale, unavailable, or reference-only</strong> rather than live.</li><li>Zenin shows a clear status instead of manufacturing values it cannot source.</li></ul><p><strong>Next:</strong> <a href="/get-started/first-portfolio-sync">First portfolio sync</a></p>',19)])])}const g=t(r,[["render",s]]);export{h as __pageData,g as default};
